/** The command: `html`, `outline`, and `defs`, each over the document on standard input. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, normalizeLabel, parse, render, splitLines } from './block.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'
const MODES = ['html', 'outline', 'defs']
const DEFINITION = /^\[([^\]]+)\]:(\s+)(\S.*)$/u

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Read a definitions file into the given map, its own failures naming the file and its own lines. */
function readDefinitions(path, definitions) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    fail(`cannot read definitions ${path}`)
    return
  }
  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const trimmed = lines[index].trim()
    const line = index + 1
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const match = DEFINITION.exec(trimmed)
    if (match === null) fail(`${path}: line ${line}: expected [label]: <url>`)
    const label = normalizeLabel(match[1])
    if (definitions.has(label)) fail(`${path}: line ${line}: label ${label} is defined twice`)
    definitions.set(label, { url: match[3], source: 'file' })
  }
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (!MODES.includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

const definitions = new Map()
if (argv.length === 2) readDefinitions(argv[1], definitions)

let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), definitions)
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  process.stdout.write(render(parsed, definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(parsed).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const sorted = [...definitions.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  const lines = sorted.map(([label, entry]) => `${label} ${entry.url} ${entry.source}\n`)
  process.stdout.write(`${lines.join('')}total ${sorted.length}\n`)
}
"}

